insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_89_v1'
from (values
('127.695.d.1.A',3,'A help desk technician stays calm, listens fully and fixes a caller''s printer issue the same day. These habits show:','["excellent customer service", "a hardware failure", "poor time management", "a security breach"]'::jsonb,0,'Patience, listening and follow-through define good service.','original'),
('127.695.d.1.A',4,'Which behavior best models excellent customer service when a caller is frustrated?','["Telling the caller to calm down", "Acknowledging the frustration and focusing on a solution", "Reading a script without listening", "Transferring the call immediately"]'::jsonb,1,'Empathy plus action builds trust.','original'),
('127.695.d.1.B',3,'When answering a support line, the best way to open a contact is to:','["ask what they did wrong", "wait silently", "greet the caller, give your name and offer help", "ask for payment first"]'::jsonb,2,'A friendly opening sets the tone.','original'),
('127.695.d.1.B',4,'After greeting a caller and giving your name, the next step in opening a contact is to:','["close the ticket", "transfer to a manager", "email a survey", "ask how you can help and gather the issue details"]'::jsonb,3,'Open with a greeting, then identify the need.','original'),
('127.695.d.1.C',3,'Using a client''s name during a support call helps to:','["build rapport and make the client feel valued", "avoid documentation", "lower the call volume", "speed up the modem"]'::jsonb,0,'Names personalize the service.','original'),
('127.695.d.1.C',4,'A technician overuses a client''s name in every sentence. This habit can:','["fix the problem faster", "sound insincere and annoy the client", "improve the connection", "protect the client''s data"]'::jsonb,1,'Moderation keeps the tone natural.','original'),
('127.695.d.1.D',3,'Which habit should a technician avoid when talking with a client?','["Speaking clearly", "Thanking the client", "Using technical jargon the client doesn''t understand", "Summarizing the issue"]'::jsonb,2,'Jargon confuses non-technical users.','original'),
('127.695.d.1.D',4,'A technician interrupts a client who is explaining a problem. This habit is harmful because it:','["improves accuracy", "lowers costs", "shortens every call", "can cause missed details and damage trust"]'::jsonb,3,'Interrupting hides key information.','original'),
('127.695.d.1.E',3,'A repair will take two extra days because a part is backordered. The technician should:','["tell the client about the delay promptly", "hope they don''t notice", "close the ticket", "wait until the client asks"]'::jsonb,0,'Clients should be kept informed.','original'),
('127.695.d.1.E',4,'Keeping clients informed of status changes mainly helps to:','["avoid documentation", "manage expectations and reduce repeat calls", "increase part costs", "hide mistakes"]'::jsonb,1,'Updates prevent frustration and follow-ups.','original'),
('127.695.d.1.F',3,'Before placing a caller on hold, a technician should:','["say nothing", "hang up", "ask permission and explain why", "mute the call silently"]'::jsonb,2,'Courtesy before hold avoids frustration.','original'),
('127.695.d.1.F',4,'When transferring a call to another department, a good practice is to:','["drop the call", "let the caller repeat everything", "transfer without telling the caller", "explain the transfer and give the next person the details"]'::jsonb,3,'Warm transfers save time.','original'),
('127.695.d.1.G',3,'A caller is shouting about a lost file. The best first response is to:','["listen, stay calm and acknowledge the concern", "shout back", "hang up", "argue about the cause"]'::jsonb,0,'De-escalation starts with calm listening.','original'),
('127.695.d.1.G',4,'When a difficult caller demands a solution outside policy, a technician should:','["promise the impossible", "explain what can be done and offer an alternative or escalation", "end the call", "ignore the request"]'::jsonb,1,'Stay honest and solution-oriented.','original'),
('127.695.d.1.H',3,'After a support call, the technician writes down the issue, steps taken and the result. This is:','["deleting evidence", "wasting time", "documenting the communication and outcome", "optional busywork"]'::jsonb,2,'Records support follow-up.','original'),
('127.695.d.1.H',4,'A well-written ticket note should be:','["vague and short", "full of slang", "left blank", "clear, accurate and professional"]'::jsonb,3,'Good notes help the next technician.','original'),
('127.695.d.2.A',3,'Which skill is most important for an IT support specialist when explaining a fix to a non-technical user?','["clear communication", "soldering", "video editing", "web design"]'::jsonb,0,'Explaining well is core to support.','original'),
('127.695.d.2.A',4,'An IT support specialist''s primary responsibilities include troubleshooting issues, documenting fixes and:','["managing payroll", "providing user assistance and escalating when needed", "designing company logos", "selling hardware"]'::jsonb,1,'Support covers help, documentation and escalation.','original'),
('127.695.d.2.B',3,'Before opening a new computer box, a technician should check for:','["music", "the weather", "visible shipping damage and verify the contents", "a login"]'::jsonb,2,'Inspection prevents later disputes.','original'),
('127.695.d.2.B',4,'Handling a hard drive safely during repacking means using:','["a plastic bag with no padding", "loose newspaper only", "rubber bands", "anti-static protection and cushioned packaging"]'::jsonb,3,'Static and shock can damage components.','original'),
('127.695.d.2.C',3,'Remote support tools let a technician fix a problem without:','["traveling to the user''s location", "any software", "an internet connection", "the user''s permission"]'::jsonb,0,'Remote tools save travel time.','original'),
('127.695.d.2.C',4,'A client needs a hardware part swapped in a locked server room. The best support method is:','["a voice mail", "in-person support", "an instant message", "a text survey"]'::jsonb,1,'Hands-on work requires being there.','original'),
('127.695.d.2.D',3,'A user emails a question and gets a written reply with steps. This is which support delivery model?','["remote desktop control", "a walk-up desk", "email support", "on-site repair"]'::jsonb,2,'Written replies are email support.','original'),
('127.695.d.2.D',4,'Support delivered by phone while the technician talks the user through steps is:','["automated support", "self-service articles", "in-person support", "telephone support"]'::jsonb,3,'Voice guidance is phone support.','original'),
('127.695.d.2.E',3,'The security management process in IT support aims to:','["protect information and systems from threats", "raise hardware prices", "remove user accounts", "increase user passwords'' length only"]'::jsonb,0,'Security management protects assets.','original'),
('127.695.d.2.E',4,'An IT support specialist supports the security process by:','["disabling updates", "following policies and reporting suspicious activity", "ignoring alerts", "sharing admin passwords"]'::jsonb,1,'Support staff are a first line of defense.','original'),
('127.695.d.3.A',3,'A technician asks questions, tests one change at a time and verifies the fix. This is:','["random guessing", "a hardware upgrade", "a troubleshooting process", "a software license"]'::jsonb,2,'Structured steps find causes.','original'),
('127.695.d.3.A',4,'After a solution restores a printer, the next step in a troubleshooting process is to:','["restart from the beginning", "delete the printer", "blame the user", "verify the fix and document the findings"]'::jsonb,3,'Verification and documentation close the loop.','original'),
('127.695.d.3.B',3,'Writing down each troubleshooting step helps because:','["it prevents repeating steps and aids later technicians", "it hides the cause", "it is never useful", "it slows the repair"]'::jsonb,0,'Notes capture what has been tried.','original'),
('127.695.d.3.B',4,'A ticket has no notes and the issue returns. The next technician will likely:','["know the exact cause", "repeat tests that were already done", "skip troubleshooting", "fix it instantly"]'::jsonb,1,'Missing notes waste time.','original'),
('127.695.d.3.C',3,'A help desk service level model sets expectations for:','["parking spots", "employee birthdays", "response and resolution times", "office decor"]'::jsonb,2,'SLAs define time targets.','original'),
('127.695.d.3.C',4,'Incident management activities include logging an issue, categorizing it and:','["firing the user", "buying new offices", "changing the logo", "resolving it and closing the ticket"]'::jsonb,3,'The incident lifecycle ends in resolution.','original'),
('127.695.d.3.D',3,'A server outage affecting everyone is best described as an:','["incident", "upgrade", "training", "warranty"]'::jsonb,0,'Incidents disrupt service.','original'),
('127.695.d.3.D',4,'The same printer jams every week for the same underlying reason. This repeating cause is called a:','["greeting", "problem", "training event", "new hire"]'::jsonb,1,'Problems are root causes of repeated incidents.','original'),
('127.695.d.3.E',3,'An operational level agreement (OLA) describes the commitments between:','["a user and their family", "two unrelated vendors", "internal teams that support a service", "a company and its customers only"]'::jsonb,2,'OLAs define internal responsibilities.','original'),
('127.695.d.3.E',4,'An IT support specialist uses an OLA to know:','["who owns the building", "what the user''s salary is", "which colors to use", "how quickly another internal team must respond to a handoff"]'::jsonb,3,'OLAs set internal response targets.','original'),
('127.695.d.3.F',3,'A technician cannot fix a network outage with the tools available. The next step is to:','["escalate to a higher-level team", "close the ticket", "delete logs", "ignore it"]'::jsonb,0,'Escalation passes unresolved issues up.','original'),
('127.695.d.3.F',4,'A reason an incident may be escalated is that it:','["has no user", "is beyond the technician''s authority or skill level", "is a duplicate greeting", "was solved quickly"]'::jsonb,1,'Escalate when you can''t resolve it.','original'),
('127.695.d.3.G',3,'Applying a security patch to a company laptop is an example of:','["a data deletion", "a license theft", "a system update", "a hardware sale"]'::jsonb,2,'Updates close known vulnerabilities.','original'),
('127.695.d.3.G',4,'Before rolling out a major update to many devices, a technician should first:','["push it to everyone at once", "turn off all computers", "skip the backup", "test it on a small group of devices"]'::jsonb,3,'Pilot testing reduces risk.','original'),
('127.695.d.3.H',3,'A service level target for a help desk could be to:','["answer 90% of calls within 60 seconds", "answer calls in a week", "ignore calls", "never record calls"]'::jsonb,0,'Targets are measurable.','original'),
('127.695.d.3.H',4,'Service center metrics such as first-call resolution rate help managers to:','["reduce staff breaks", "measure and improve support quality", "buy more office plants", "raise rent"]'::jsonb,1,'Metrics guide improvement.','original'),
('127.695.d.4.A',3,'A student uses the school''s computers only for approved class work, as the acceptable use policy states. This shows:','["a policy violation", "poor planning", "positive digital citizenship", "a network fault"]'::jsonb,2,'Following policy is responsible behavior.','original'),
('127.695.d.4.A',4,'Posting a kind, accurate comment on a class forum and reporting a rude one shows:','["spamming", "trolling", "identity theft", "responsible digital citizenship"]'::jsonb,3,'Respectful action builds a positive online community.','original'),
('127.695.d.4.B',3,'Which password change makes it hardest for attackers to guess?','["Making it longer and adding unrelated words and symbols", "Using the word ''password''", "Using your birthday", "Using your pet''s name only"]'::jsonb,0,'Length and variety increase strength.','original'),
('127.695.d.4.B',4,'A good practice for protecting accounts is to:','["write it on a sticky note on the monitor", "use a different strong password for each account", "share it with coworkers", "reuse one password everywhere"]'::jsonb,1,'Unique passwords limit breach damage.','original'),
('127.695.d.4.C',3,'Before using a student''s photo in a school newsletter, staff should follow guidelines on:','["paper weight", "font choices", "permission and privacy", "printer speed"]'::jsonb,2,'Media use requires consent.','original'),
('127.695.d.4.C',4,'A technician receives a request to post an employee''s personal details online. The guidelines say to:','["ignore all rules", "email it to everyone", "post it right away", "verify authorization and protect private information"]'::jsonb,3,'Privacy guidelines limit disclosure.','original'),
('127.695.d.4.D',3,'A work published for anyone to use freely, with no copyright restrictions, is in the:','["public domain", "trade secret", "patent office", "private archive"]'::jsonb,0,'Public domain works are free to use.','original'),
('127.695.d.4.D',4,'A photographer lets others reuse her photo if they give credit. This is typical of a:','["trade secret", "Creative Commons license", "trademark", "patent"]'::jsonb,1,'Creative Commons allows reuse with conditions.','original'),
('127.695.d.4.E',3,'A company buys 10 software licenses but installs the program on 40 computers. This violates:','["a color rule", "a file naming rule", "the software licensing terms", "a font rule"]'::jsonb,2,'Licenses limit installations.','original'),
('127.695.d.4.E',4,'A technician finds an unlicensed copy of paid software on a workstation. The correct action is to:','["hide it", "copy it to more machines", "ignore it", "report it and bring the license into compliance"]'::jsonb,3,'Compliance protects the company.','original'),
('127.695.d.4.F',3,'Encryption protects data by:','["scrambling it so only authorized users can read it", "printing it", "compressing it only", "deleting it"]'::jsonb,0,'Encryption makes data unreadable without a key.','original'),
('127.695.d.4.F',4,'A lost laptop with an encrypted drive is less risky because:','["the battery is dead", "the data cannot be read without the key", "the laptop can''t be sold", "the screen is locked forever"]'::jsonb,1,'Encryption protects data at rest.','original'),
('127.695.d.4.G',3,'A technician sees a customer''s account number on a screen while repairing a computer. Best practice is to:','["email it to coworkers", "write it on a whiteboard", "avoid copying or sharing it", "post it online"]'::jsonb,2,'Confidential data stays confidential.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_89_v1'
from (values
('127.695.d.4.G',4,'Confidential paper records that are no longer needed should be:','["thrown in the recycling bin whole", "left on a desk", "mailed to a friend", "securely shredded"]'::jsonb,3,'Proper destruction prevents leaks.','original'),
('127.695.d.4.H',3,'An email pretends to be from the IT department and asks for a user''s password. This is an example of:','["social engineering", "a software update", "a backup", "a hardware warranty"]'::jsonb,0,'Attackers manipulate people to get information.','original'),
('127.695.d.4.H',4,'A good way to reduce the risk of social engineering is to:','["click all links quickly", "verify unexpected requests through a known, trusted channel", "ignore training", "share passwords on request"]'::jsonb,1,'Verification stops impersonation.','original'),
('127.695.d.4.I',3,'A policy that says visitors must sign in and wear badges is a:','["software patch", "password reset", "physical security measure", "network protocol"]'::jsonb,2,'Badges and logs control physical access.','original'),
('127.695.d.4.I',4,'Physical security matters in IT because someone with physical access to a server can often:','["delete the laws", "repair the policy", "improve the network", "bypass software protections"]'::jsonb,3,'Physical access can defeat digital controls.','original'),
('127.695.d.4.J',3,'A user notices strange pop-ups after opening an email attachment. They should:','["report it to IT support right away", "ignore it", "turn off the monitor", "forward the attachment"]'::jsonb,0,'Prompt reporting limits damage.','original'),
('127.695.d.4.J',4,'Reporting a security compromise promptly helps because it:','["hides the cause", "lets the organization contain and fix the problem sooner", "raises the budget", "increases downtime"]'::jsonb,1,'Speed limits harm.','original'),
('127.695.d.4.K',3,'Before donating an old computer, a technician should:','["delete only the desktop icons", "leave all files on it", "wipe or destroy the drive so data can''t be recovered", "write passwords inside the case"]'::jsonb,2,'Proper sanitization protects data.','original'),
('127.695.d.4.K',4,'Which method most reliably prevents data recovery from a retired hard drive?','["Emptying the recycle bin", "Renaming the files", "Moving files to another folder", "Physical destruction or certified wiping"]'::jsonb,3,'Deleting files is not enough.','original'),
('127.695.d.5.A',3,'Before installing a CPU, a technician should:','["power off, unplug and use anti-static protection", "touch the pins", "leave the power on", "wear wool gloves"]'::jsonb,0,'ESD and power safety come first.','original'),
('127.695.d.5.A',4,'When installing a processor on a motherboard, the technician must line up:','["the cables with the fan", "the notch or triangle marker with the socket", "the label with the monitor", "the heat sink with the case door"]'::jsonb,1,'Alignment marks prevent bent pins.','original'),
('127.695.d.5.B',3,'A basic way to secure a workstation is to require:','["no login at all", "a shared admin account for all", "a login password and a locked screen when away", "default passwords forever"]'::jsonb,2,'Access control protects the workstation.','original'),
('127.695.d.5.B',4,'Securing a workstation also includes keeping the operating system and software:','["unlicensed", "exactly as shipped", "turned off", "up to date with security patches"]'::jsonb,3,'Patching closes vulnerabilities.','original'),
('127.695.d.5.C',3,'A computer shows no lights and no fan spin when the power button is pressed. This symptom is called:','["no power", "a POST beep error", "a blue screen", "a slow network"]'::jsonb,0,'No power suggests a supply or outlet problem.','original'),
('127.695.d.5.C',4,'A system powers on but fails before the operating system loads and gives beep codes. The problem is detected during:','["a Windows update", "POST (power-on self-test)", "a web search", "a screen saver"]'::jsonb,1,'POST checks hardware at startup.','original'),
('127.695.d.5.D',3,'A machine shows memory errors. A technician can troubleshoot by:','["updating the web browser", "reinstalling the printer", "reseating or replacing the RAM modules", "replacing the monitor cable"]'::jsonb,2,'RAM modules can loosen or fail.','original'),
('127.695.d.5.D',4,'When installing new RAM, the notch on the module must match:','["the fan size", "the logo", "the case color", "the key in the slot"]'::jsonb,3,'Keys ensure correct orientation.','original'),
('127.695.d.5.E',3,'A computer overheats and shuts down. A technician should first check and clean:','["the fans and heat sink for dust", "the speaker cone", "the mouse ball", "the keyboard keys"]'::jsonb,0,'Dust blocks airflow.','original'),
('127.695.d.5.E',4,'Thermal paste is applied between a CPU and its cooler to:','["lower the voltage", "improve heat transfer", "glue the case shut", "paint the board"]'::jsonb,1,'Paste fills microscopic gaps.','original'),
('127.695.d.5.F',3,'Cleaning fans and checking cables on a regular schedule is called:','["a hardware recall", "a data wipe", "periodic maintenance", "a license audit"]'::jsonb,2,'Routine upkeep prevents failure.','original'),
('127.695.d.5.F',4,'Software maintenance tasks include installing updates and:','["painting the tower", "replacing the case", "removing the fan", "running disk cleanup and scans"]'::jsonb,3,'Regular software upkeep keeps systems healthy.','original'),
('127.695.d.5.G',3,'A technician suspects malware. The first sensible step is usually to:','["isolate the computer from the network", "delete the operating system", "share files with others", "plug in more drives"]'::jsonb,0,'Isolation stops spread.','original'),
('127.695.d.5.G',4,'After removing malware with an approved tool, a technician should:','["share the infected file", "update the system and scan again to confirm it is clean", "assume it is clean", "reinfect to test"]'::jsonb,1,'Verification confirms removal.','original'),
('127.695.d.6.A',3,'A user cannot find a lost file. A built-in OS feature to try is:','["a screwdriver", "a router reset", "the search tool", "a toner cartridge"]'::jsonb,2,'OS search locates files.','original'),
('127.695.d.6.A',4,'A technician wants to see which programs slow a computer at startup. The OS tool to use is:','["a spreadsheet", "a printer spooler", "a web browser", "the task or startup manager"]'::jsonb,3,'Startup managers list launch items.','original'),
('127.695.d.6.B',3,'To check how much free space a drive has, a technician can use:','["the disk management or storage utility", "a word processor", "an email client", "a calculator"]'::jsonb,0,'Storage utilities show space.','original'),
('127.695.d.6.B',4,'A utility that rearranges data on a traditional hard disk so files are stored more efficiently is:','["encryption", "defragmentation", "compression of photos", "a firewall"]'::jsonb,1,'Defragmentation reduces seek time on HDDs.','original'),
('127.695.d.6.C',3,'On Windows, the command used to show a computer''s network configuration is:','["diskpart only", "notepad", "ipconfig", "format"]'::jsonb,2,'ipconfig lists IP settings.','original'),
('127.695.d.6.C',4,'To see active network connections and listening ports, a technician types:','["ping only", "dir", "cls", "netstat"]'::jsonb,3,'netstat shows connections.','original'),
('127.695.d.6.D',3,'A computer frequently shows a blue error screen after a driver update. A sensible first step is to:','["roll back or update the driver", "buy a new keyboard", "replace the monitor", "reinstall the printer paper"]'::jsonb,0,'Drivers cause many OS crashes.','original'),
('127.695.d.6.D',4,'After solving an OS problem, a technician records the symptoms, steps taken and the:','["stock price", "final resolution", "weather", "coffee order"]'::jsonb,1,'Documentation helps future fixes.','original'),
('127.695.d.6.E',3,'A technician working on macOS should expect to find system settings in:','["Control Panel only", "a DOS prompt only", "System Settings (or System Preferences)", "the BIOS only"]'::jsonb,2,'Each OS has its own tools.','original'),
('127.695.d.6.E',4,'A Linux user can run commands and manage files using the:','["dock bell", "charms bar", "start orb", "terminal"]'::jsonb,3,'The terminal is Linux''s command interface.','original'),
('127.695.d.6.F',3,'A Windows laptop won''t boot but a Mac and a Linux laptop work fine. A technician should troubleshoot:','["the Windows laptop''s own OS and hardware", "the Linux partition", "the network cable of the Mac", "the Mac''s fan"]'::jsonb,0,'Troubleshoot the affected system.','original'),
('127.695.d.6.F',4,'When documenting problems across several operating systems, a technician should note the:','["favorite color", "OS name, version and symptoms", "break times", "lunch order"]'::jsonb,1,'Details help reproduce issues.','original'),
('127.695.d.6.G',3,'A database is used to:','["connect keyboards", "print posters", "store, organize and retrieve data", "cool servers"]'::jsonb,2,'Databases manage data.','original'),
('127.695.d.6.G',4,'In a database table, a single row of data about one customer is called a:','["protocol", "cable", "field type", "record"]'::jsonb,3,'Rows are records.','original'),
('127.695.d.7.A',3,'A new solid-state drive is installed in a laptop but the OS does not see it. The technician should first check that:','["the drive is detected in BIOS/UEFI and initialized", "the monitor is bright", "the printer has paper", "the keyboard is clean"]'::jsonb,0,'Detect, then initialize and format.','original'),
('127.695.d.7.A',4,'A drive that makes clicking noises and is slow is most likely showing signs of:','["a loose mouse", "mechanical failure", "a network outage", "a printer jam"]'::jsonb,1,'Clicking indicates failing moving parts.','original'),
('127.695.d.7.B',3,'A laser printer produces pages with black streaks. A common cause to check is:','["a loose monitor", "a bad mouse", "a dirty or damaged drum or toner cartridge", "a slow modem"]'::jsonb,2,'Streaks often come from toner or drum issues.','original'),
('127.695.d.7.B',4,'A multifunction office device can usually print, copy, scan and:','["compile code", "store passwords", "edit video", "fax"]'::jsonb,3,'MFDs combine several functions.','original'),
('127.695.d.7.C',3,'A projector shows a dim, yellowed image. The most likely maintenance item to check is the:','["lamp (bulb) life and filters", "keyboard", "printer", "mouse"]'::jsonb,0,'Aging lamps dim and shift color.','original'),
('127.695.d.7.C',4,'A monitor displays ''no signal'' after a computer is turned on. A first check is the:','["printer driver", "video cable connection and input source", "hard drive speed", "email settings"]'::jsonb,1,'Cable and input selection cause most no-signal cases.','original'),
('127.695.d.7.D',3,'A conference attendee cannot be heard on a video call. A technician should first check the:','["keyboard layout", "printer queue", "microphone connection, mute status and input selection", "monitor brightness"]'::jsonb,2,'Mute and input settings are common culprits.','original'),
('127.695.d.7.D',4,'A webcam works in one app but not another. A likely cause is:','["a dead power supply", "a full printer queue", "a broken keyboard", "the second app lacks permission or is using the wrong camera"]'::jsonb,3,'Per-app permissions and device selection matter.','original'),
('127.695.d.8.A',3,'Laptop hardware differs from desktop hardware because laptop parts are often:','["smaller and integrated into a compact case", "free of any battery", "not repairable by anyone", "bigger and always removable"]'::jsonb,0,'Laptops use compact, tightly integrated components.','original'),
('127.695.d.8.A',4,'Before replacing a laptop''s internal RAM, a technician should:','["skip static protection", "power off, disconnect the battery and AC adapter, and ground themselves", "leave the laptop on", "remove the screen"]'::jsonb,1,'Safety first protects the technician and parts.','original'),
('127.695.d.8.B',3,'A laptop screen is cracked. Replacing it requires carefully removing the:','["the keyboard only", "power cord only", "bezel and the display panel connector", "the printer"]'::jsonb,2,'Access to the display is through the bezel.','original'),
('127.695.d.8.B',4,'A technician replacing an internal display panel should handle the video ribbon cable:','["by pulling hard", "by cutting it", "with wet hands", "gently to avoid tearing or bending it"]'::jsonb,3,'Ribbon cables are fragile.','original'),
('127.695.d.8.C',3,'A user wants to connect an external monitor to a laptop. The technician should look for a:','["video output port such as HDMI or USB-C", "speaker jack only", "power button", "card slot for a printer"]'::jsonb,0,'Video ports connect displays.','original'),
('127.695.d.8.C',4,'A docking station helps a laptop user by providing:','["more battery life by itself", "multiple ports and charging through one connection", "a larger processor", "a faster keyboard"]'::jsonb,1,'Docks consolidate connections.','original'),
('127.695.d.8.D',3,'A basic way to secure a mobile phone is to enable:','["an open Wi-Fi hotspot", "auto-share of all data", "a screen lock with a PIN or biometric", "no lock"]'::jsonb,2,'Screen locks block unauthorized access.','original'),
('127.695.d.8.D',4,'If a company phone is lost, which feature can protect its data?','["screen brightness", "auto-rotate", "wallpaper change", "remote wipe"]'::jsonb,3,'Remote wipe erases data on a lost device.','original'),
('127.695.d.8.E',3,'A phone connects to Wi-Fi but cannot load web pages. A technician should check:','["the network settings and credentials", "the case color", "the speaker volume", "the camera lens"]'::jsonb,0,'Connectivity issues point to network settings.','original'),
('127.695.d.8.E',4,'Company email on a phone requires a:','["game controller", "configured account with the correct server settings", "printer cable", "screen protector"]'::jsonb,1,'App support needs correct account configuration.','original')
